// ADSR envelope: Gate a constant tone through the core audio-rate envelope. Switch Gate on and off to hear attack and release.
// Audition composition of public Rust primitives; not an instrument parity claim.
// Examples name imports so you can trace each tool to its module.
// Alternative: import * as manifold from '@manifold/author';
// Then use manifold.createGraphWorkspace(), manifold.gain, etc.
// Imports — each definition can be inspected in Manifold's primitive catalog.
import { createGraphWorkspace } from '@manifold/author';
import {
  oscillator as oscillatorDefinition,
  adsr as adsrDefinition,
} from '@manifold/author/primitives';

export default function createProject() {
  // Interface — public paths and stable IDs preserve saved controls.
  const controls = {
    oscillator_waveform: {
      "path": "/primitives/adsr/node/0",
      "label": "Waveform",
      "group": "Oscillator",
      "min": 0,
      "max": 4,
      "default": 0,
      "choices": [
        "Sine",
        "Saw",
        "Square",
        "Triangle",
        "Blend"
      ]
    },
    oscillator_frequency: {
      "path": "/primitives/adsr/node/1",
      "label": "Frequency",
      "group": "Oscillator",
      "min": 20,
      "max": 16000,
      "default": 220
    },
    oscillator_level: {
      "path": "/primitives/adsr/node/2",
      "label": "Level",
      "group": "Oscillator",
      "min": 0,
      "max": 1,
      "default": 0.16
    },
    envelope_attack: {
      "path": "/primitives/adsr/envelope/0",
      "label": "Attack",
      "group": "ADSR",
      "min": 0.001,
      "max": 5,
      "default": 0.05
    },
    envelope_decay: {
      "path": "/primitives/adsr/envelope/1",
      "label": "Decay",
      "group": "ADSR",
      "min": 0.001,
      "max": 5,
      "default": 0.2
    },
    envelope_sustain: {
      "path": "/primitives/adsr/envelope/2",
      "label": "Sustain",
      "group": "ADSR",
      "min": 0,
      "max": 1,
      "default": 0.7
    },
    envelope_release: {
      "path": "/primitives/adsr/envelope/3",
      "label": "Release",
      "group": "ADSR",
      "min": 0.001,
      "max": 10,
      "default": 0.4
    },
    envelope_gate: {
      "path": "/primitives/adsr/envelope/4",
      "label": "Gate",
      "group": "ADSR",
      "min": 0,
      "max": 1,
      "default": 0,
      "choices": [
        "Off",
        "On"
      ]
    },
  };

  // Audio inputs and outputs — generated sound; no audio input is needed.
  const graph = createGraphWorkspace().setInputSource('none');
  const output = graph.output.input('in');

  // DSP instances — parameters belong to these named instances.
  const oscillator = graph.add(oscillatorDefinition.type, {"id":4});
  graph.registerInstance('/primitives/adsr/node', oscillator);
  oscillator.parameter('waveform').expose(controls.oscillator_waveform);
  oscillator.parameter('frequency').expose(controls.oscillator_frequency);
  oscillator.parameter('level').expose(controls.oscillator_level);

  const envelope = graph.add(adsrDefinition.type, {"id":5});
  graph.registerInstance('/primitives/adsr/envelope', envelope);
  envelope.parameter('attack').expose(controls.envelope_attack);
  envelope.parameter('decay').expose(controls.envelope_decay);
  envelope.parameter('sustain').expose(controls.envelope_sustain);
  envelope.parameter('release').expose(controls.envelope_release);
  envelope.parameter('gate').expose(controls.envelope_gate);

  // Composition — named ports make the audio and control paths visible.
  graph.connect(oscillator.output('out'), envelope.input('audio'));
  graph.connect(envelope.output('out'), output);

  // Presentation — both renderers bind to the controls declared above.
  const view = [
    controls.oscillator_waveform,
    controls.oscillator_frequency,
    controls.oscillator_level,
    controls.envelope_attack,
    controls.envelope_decay,
    controls.envelope_sustain,
    controls.envelope_release,
    controls.envelope_gate
  ].map(control => ({
    id: control.path, type: 'parameter', path: control.path,
    label: control.label, group: control.group,
    ...(control.choices ? { choices: control.choices } : {}),
  }));
  function paint(ui) {
    for (const component of view) {
      if (component.type === 'label') ui.label(component.label, component.id);
      else ui.parameter(component.path, component);
    }
  }

  // The host uses this project declaration for audio, UI, save and live edits.
  return { graph, view, paint };
}
